package com.example.billing.service;
import static com.example.billing.api.Contracts.*;import static com.example.billing.domain.BillingConstants.*;import com.example.billing.domain.*;import com.example.billing.persistence.Repositories.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
@Service public class PaymentService {public enum Outcome{CREATED,EXISTING,FAILED}public record Result(Outcome outcome,int statusCode,Payment payment,String errorCode,String errorMessage){}private final InvoiceRepository invoices;private final PaymentRepository payments;private final IdempotencyRecordRepository records;private final KeyedLock locks;private final Clock clock;private final TransactionTemplate transactions;public PaymentService(InvoiceRepository i,PaymentRepository p,IdempotencyRecordRepository r,KeyedLock l,Clock c,PlatformTransactionManager tx){invoices=i;payments=p;records=r;locks=l;clock=c;transactions=new TransactionTemplate(tx);}public Result pay(UUID invoiceId,PayInvoiceRequest input,String key){var request=new PayInvoiceRequest(input.provider()==null||input.provider().isBlank()?"test_gateway":input.provider().trim(),input.simulateFailure());var hash=hash(invoiceId,request);try(var ignored=locks.acquire("idempotency:"+key)){return transactions.execute(s->payLocked(invoiceId,request,key,hash));}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}private Result payLocked(UUID invoiceId,PayInvoiceRequest request,String key,String hash){var old=records.findByKey(key).orElse(null);if(old!=null)return existing(old,hash);var now=OffsetDateTime.now(clock);var r=new IdempotencyRecord();r.id=UUID.randomUUID();r.key=key;r.requestHash=hash;r.status=IdempotencyStatus.IN_PROGRESS;r.createdAt=now;r.updatedAt=now;try{r=records.saveAndFlush(r);}catch(DataIntegrityViolationException e){return existing(records.findByKey(key).orElseThrow(()->e),hash);}return execute(invoiceId,request,r);}private Result execute(UUID invoiceId,PayInvoiceRequest request,IdempotencyRecord r){try(var ignored=locks.acquire("invoice-payment:"+invoiceId)){var invoice=invoices.findById(invoiceId).orElse(null);if(invoice==null)return failRecord(r,404,"invoice_not_found","Invoice does not exist.");if(InvoiceStatus.PAID.equals(invoice.status))return failRecord(r,409,"invoice_already_paid","Invoice is already paid.");if(!InvoiceStatus.OPEN.equals(invoice.status))return failRecord(r,409,"invoice_not_payable","Invoice with status '"+invoice.status+"' cannot be paid.");var amount=invoice.amountDue.subtract(invoice.amountPaid);if(amount.signum()<=0)return failRecord(r,409,"invoice_balance_not_due","Invoice does not have an amount due.");var p=build(invoice.id,amount,request,r.key);if(request.simulateFailure()){p.attempts.getFirst().failureReason="Simulated payment gateway failure.";payments.save(p);r.status=IdempotencyStatus.FAILED;r.statusCode=502;r.responsePaymentId=p.id;r.errorCode="payment_gateway_failed";r.errorMessage="Payment gateway failed to charge the payment method.";r.updatedAt=OffsetDateTime.now(clock);return new Result(Outcome.FAILED,502,p,r.errorCode,r.errorMessage);}p.status=PaymentStatus.SUCCEEDED;p.attempts.getFirst().status=PaymentStatus.SUCCEEDED;invoice.amountPaid=invoice.amountPaid.add(amount);invoice.status=InvoiceStatus.PAID;payments.save(p);r.status=IdempotencyStatus.COMPLETED;r.statusCode=201;r.responsePaymentId=p.id;r.updatedAt=OffsetDateTime.now(clock);return new Result(Outcome.CREATED,201,p,null,null);}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}private Result existing(IdempotencyRecord r,String hash){if(!r.requestHash.equals(hash))return fail(409,"idempotency_key_reused","Idempotency-Key was already used for a different request.");if(IdempotencyStatus.FAILED.equals(r.status))return fail(r.statusCode==null?500:r.statusCode,r.errorCode==null?"payment_failed":r.errorCode,r.errorMessage==null?"Payment failed.":r.errorMessage);if(r.responsePaymentId!=null){var p=payments.findById(r.responsePaymentId).orElse(null);if(p!=null)return new Result(Outcome.EXISTING,200,p,null,null);}return fail(409,"idempotency_request_in_progress","A payment request with this Idempotency-Key is still in progress.");}private Payment build(UUID invoice,BigDecimal amount,PayInvoiceRequest r,String key){var now=OffsetDateTime.now(clock);var p=new Payment();p.id=UUID.randomUUID();p.invoiceId=invoice;p.amount=amount;p.status=PaymentStatus.FAILED;p.provider=r.provider();p.idempotencyKey=key;p.createdAt=now;var a=new PaymentAttempt();a.id=UUID.randomUUID();a.payment=p;a.attemptNumber=1;a.status=PaymentStatus.FAILED;a.createdAt=now;p.attempts.add(a);return p;}private Result failRecord(IdempotencyRecord r,int s,String c,String m){r.status=IdempotencyStatus.FAILED;r.statusCode=s;r.errorCode=c;r.errorMessage=m;r.updatedAt=OffsetDateTime.now(clock);return fail(s,c,m);}private static Result fail(int s,String c,String m){return new Result(Outcome.FAILED,s,null,c,m);}private static String hash(UUID id,PayInvoiceRequest r){try{var v="POST:/invoices/"+id.toString().replace("-","")+"/pay|provider="+r.provider()+"|simulateFailure="+(r.simulateFailure()?"True":"False");return HexFormat.of().withUpperCase().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
